from PIL import Image,ImageDraw,ImageFont
f=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',22)
import os;os.makedirs('crop2',exist_ok=True)
keys=list(C);W,H=300,400
for k in keys:
    im=Image.open(f'big/{k}.jpg').convert('RGB');w,h=im.size;c=C[k]
    im.crop((int(c[0]*w),int(c[1]*h),int(c[2]*w),int(c[3]*h))).save(f'crop2/{k}.jpg',quality=90)
for s in range(0,len(keys),20):
    sh=Image.new('RGB',(W*5,(H+30)*4),'white');d=ImageDraw.Draw(sh)
    for i,k in enumerate(keys[s:s+20]):
        im=Image.open(f'crop2/{k}.jpg');im.thumbnail((W,H));X,Y=(i%5)*W,(i//5)*(H+30)
        sh.paste(im,(X,Y+30));d.text((X+4,Y+2),k,fill='red',font=f)
    sh.save(f'sheets2/c{s//20:02d}.jpg',quality=85)
print(len(keys))
